-- tipo: SQL | Espelho publico da SF 126 (driver modo pacote) escopado por token+posse do pacote. Inclui RATEIOS/RATEIO_ITENS p/ distribuicao on-the-fly. Params: token,pkgId,cicloId,ano,anoPrev,controlCicloId
SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('CR_ID',x.CR_ID)) FROM (SELECT DISTINCT crc2.CR_ID FROM CR_CONTA crc2
 LEFT JOIN CONTA_DRIVER_EXCECAO cde2 ON cde2.CR_ID = crc2.CR_ID AND cde2.CONTA_ID = crc2.CONTA_ID AND cde2.ATIVO = true
 LEFT JOIN CONTA_DRIVER cd2 ON cd2.CONTA_ID = crc2.CONTA_ID
 WHERE crc2.ATIVO = true AND COALESCE(cde2.PACOTE_ID, cd2.PACOTE_ID, cde2.DRIVER_ID, cd2.DRIVER_ID) = {{pkgId}}) x),JSON_ARRAY()) AS CR_IDS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'DRIVER_ID',t.DRIVER_ID,'TIPO_RATEIO',t.TIPO_RATEIO,'BASE_PROPORCIONAL',t.BASE_PROPORCIONAL,'CRIADO_EM',t.CRIADO_EM)) FROM RATEIO_CONFIG t WHERE t.ID = (SELECT MAX(ID) FROM RATEIO_CONFIG WHERE DRIVER_ID = {{pkgId}})),JSON_ARRAY()) AS RATEIO_CONFIG,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'RATEIO_CONFIG_ID',t.RATEIO_CONFIG_ID,'CR_ID',t.CR_ID,'PERCENTUAL',t.PERCENTUAL)) FROM RATEIO_CR t WHERE t.RATEIO_CONFIG_ID = (SELECT MAX(ID) FROM RATEIO_CONFIG WHERE DRIVER_ID = {{pkgId}})),JSON_ARRAY()) AS RATEIO_CR,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('CR_ID',crc.CR_ID,'CR_CODIGO',cr.CODIGO,'CR_NOME',cr.NOME,'CONTA_ID',cc.ID,'CODIGO',cc.CODIGO,'CONTA_NOME',cc.NOME,'TIPO',cc.TIPO,'DRIVER_TIPO',d.NOME,'DRIVER_ID',d.ID))
 FROM CR_CONTA crc
 JOIN CONTA_CONTABIL cc ON cc.ID = crc.CONTA_ID
 LEFT JOIN CENTRO_RESULTADO cr ON cr.ID = crc.CR_ID
 LEFT JOIN CONTA_DRIVER_EXCECAO cde ON cde.CR_ID = crc.CR_ID AND cde.CONTA_ID = crc.CONTA_ID AND cde.ATIVO = true
 LEFT JOIN CONTA_DRIVER cd ON cd.CONTA_ID = crc.CONTA_ID
 LEFT JOIN DRIVERS d ON d.ID = COALESCE(cde.DRIVER_ID, cd.DRIVER_ID)
 WHERE COALESCE(cde.PACOTE_ID, cd.PACOTE_ID, cde.DRIVER_ID, cd.DRIVER_ID) = {{pkgId}}
   AND crc.ATIVO = true AND d.ID IS NOT NULL AND d.ATIVO = 'true' AND d.TIPO_DRIVER = 'NORMAL'),JSON_ARRAY()) AS CONFIGS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',op.ID,'CONTA_ID',op.CONTA_ID,'MES',op.MES,'CR_ID',op.CR_ID,'VALOR',op.VALOR)) FROM ORCAMENTO_PACOTE op WHERE op.CICLO_ID = {{cicloId}} AND op.DRIVER_ID = {{pkgId}}),JSON_ARRAY()) AS BUDGET,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'EMPRESA_ID',t.EMPRESA_ID,'CR_ID',t.CR_ID,'CONTA_ID',t.CONTA_ID,'ANO',t.ANO,'MES',t.MES,'VALOR',t.VALOR)) FROM REALIZADO_CONTABIL t WHERE t.ANO = {{anoPrev}} AND t.CR_ID IN (SELECT DISTINCT crc2.CR_ID FROM CR_CONTA crc2
 LEFT JOIN CONTA_DRIVER_EXCECAO cde2 ON cde2.CR_ID = crc2.CR_ID AND cde2.CONTA_ID = crc2.CONTA_ID AND cde2.ATIVO = true
 LEFT JOIN CONTA_DRIVER cd2 ON cd2.CONTA_ID = crc2.CONTA_ID
 WHERE crc2.ATIVO = true AND COALESCE(cde2.PACOTE_ID, cd2.PACOTE_ID, cde2.DRIVER_ID, cd2.DRIVER_ID) = {{pkgId}})),JSON_ARRAY()) AS REALIZADO,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'EMPRESA_ID',t.EMPRESA_ID,'CR_ID',t.CR_ID,'CONTA_ID',t.CONTA_ID,'ANO',t.ANO,'MES',t.MES,'VALOR',t.VALOR)) FROM REALIZADO_CONTABIL t WHERE t.ANO = {{ano}} AND t.CR_ID IN (SELECT DISTINCT crc2.CR_ID FROM CR_CONTA crc2
 LEFT JOIN CONTA_DRIVER_EXCECAO cde2 ON cde2.CR_ID = crc2.CR_ID AND cde2.CONTA_ID = crc2.CONTA_ID AND cde2.ATIVO = true
 LEFT JOIN CONTA_DRIVER cd2 ON cd2.CONTA_ID = crc2.CONTA_ID
 WHERE crc2.ATIVO = true AND COALESCE(cde2.PACOTE_ID, cd2.PACOTE_ID, cde2.DRIVER_ID, cd2.DRIVER_ID) = {{pkgId}})),JSON_ARRAY()) AS REALIZADO_ATUAL,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',op.ID,'CONTA_ID',op.CONTA_ID,'MES',op.MES,'CR_ID',op.CR_ID,'VALOR',op.VALOR)) FROM ORCAMENTO_PACOTE op WHERE op.CICLO_ID = {{controlCicloId}} AND op.DRIVER_ID = {{pkgId}}),JSON_ARRAY()) AS ORC_CONTROLE,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'NOME',t.NOME,'CR_ID',t.CR_ID,'EMPRESA_ID',t.EMPRESA_ID,'CARGO',t.CARGO,'DATA_ADMISSAO',t.DATA_ADMISSAO,'SALARIO',t.SALARIO,'TIPO_CONTRATO',t.TIPO_CONTRATO,'ATIVO',t.ATIVO)) FROM COLABORADOR t WHERE t.ATIVO = 'true' AND t.CR_ID IN (SELECT DISTINCT crc2.CR_ID FROM CR_CONTA crc2
 LEFT JOIN CONTA_DRIVER_EXCECAO cde2 ON cde2.CR_ID = crc2.CR_ID AND cde2.CONTA_ID = crc2.CONTA_ID AND cde2.ATIVO = true
 LEFT JOIN CONTA_DRIVER cd2 ON cd2.CONTA_ID = crc2.CONTA_ID
 WHERE crc2.ATIVO = true AND COALESCE(cde2.PACOTE_ID, cd2.PACOTE_ID, cde2.DRIVER_ID, cd2.DRIVER_ID) = {{pkgId}})),JSON_ARRAY()) AS COLABORADORES,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'CICLO_ID',t.CICLO_ID,'CR_ID',t.CR_ID,'COLABORADOR_ID',t.COLABORADOR_ID,'MES',t.MES,'SALARIO',t.SALARIO,'BENEFICIOS',t.BENEFICIOS,'ENCARGOS',t.ENCARGOS,'TOTAL',t.TOTAL)) FROM ORCAMENTO_PESSOAL t WHERE t.CICLO_ID = {{cicloId}} AND t.CR_ID IN (SELECT DISTINCT crc2.CR_ID FROM CR_CONTA crc2
 LEFT JOIN CONTA_DRIVER_EXCECAO cde2 ON cde2.CR_ID = crc2.CR_ID AND cde2.CONTA_ID = crc2.CONTA_ID AND cde2.ATIVO = true
 LEFT JOIN CONTA_DRIVER cd2 ON cd2.CONTA_ID = crc2.CONTA_ID
 WHERE crc2.ATIVO = true AND COALESCE(cde2.PACOTE_ID, cd2.PACOTE_ID, cde2.DRIVER_ID, cd2.DRIVER_ID) = {{pkgId}})),JSON_ARRAY()) AS ORCAMENTO_PESSOAL,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'CICLO_ID',t.CICLO_ID,'CR_ID',t.CR_ID,'CARGO_ID',t.CARGO_ID,'MES',t.MES,'QUANTIDADE',t.QUANTIDADE)) FROM PROJECAO_HEADCOUNT t WHERE t.CICLO_ID = {{cicloId}} AND t.CR_ID IN (SELECT DISTINCT crc2.CR_ID FROM CR_CONTA crc2
 LEFT JOIN CONTA_DRIVER_EXCECAO cde2 ON cde2.CR_ID = crc2.CR_ID AND cde2.CONTA_ID = crc2.CONTA_ID AND cde2.ATIVO = true
 LEFT JOIN CONTA_DRIVER cd2 ON cd2.CONTA_ID = crc2.CONTA_ID
 WHERE crc2.ATIVO = true AND COALESCE(cde2.PACOTE_ID, cd2.PACOTE_ID, cde2.DRIVER_ID, cd2.DRIVER_ID) = {{pkgId}})),JSON_ARRAY()) AS HEADCOUNT,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',cp.ID,'CICLO_ID',cp.CICLO_ID,'CR_ID',cp.CR_ID,'CARGO_ID',cp.CARGO_ID,'MES_ENTRADA',cp.MES_ENTRADA,'MOTIVO',cp.MOTIVO,'CRIADO_EM',cp.CRIADO_EM,'QTD_VAGAS',cp.QTD_VAGAS,'JUSTIFICATIVA',cp.JUSTIFICATIVA,'CARGO_NOME',cg.NOME,'SALARIO_MEDIO',cg.SALARIO_MEDIO)) FROM CONTRATACAO_PROJETADA cp JOIN CARGO cg ON cg.ID = cp.CARGO_ID WHERE cp.CICLO_ID = {{cicloId}} AND cp.CR_ID IN (SELECT DISTINCT crc2.CR_ID FROM CR_CONTA crc2
 LEFT JOIN CONTA_DRIVER_EXCECAO cde2 ON cde2.CR_ID = crc2.CR_ID AND cde2.CONTA_ID = crc2.CONTA_ID AND cde2.ATIVO = true
 LEFT JOIN CONTA_DRIVER cd2 ON cd2.CONTA_ID = crc2.CONTA_ID
 WHERE crc2.ATIVO = true AND COALESCE(cde2.PACOTE_ID, cd2.PACOTE_ID, cde2.DRIVER_ID, cd2.DRIVER_ID) = {{pkgId}})),JSON_ARRAY()) AS CONTRATACOES,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',pd.ID,'CICLO_ID',pd.CICLO_ID,'EMPRESA_ID',pd.EMPRESA_ID,'PERCENTUAL',pd.PERCENTUAL,'MES_APLICACAO',pd.MES_APLICACAO,'CRIADO_EM',pd.CRIADO_EM,'EMPRESA_NOME',e.NOME)) FROM PREMISSA_DISSIDIO pd JOIN EMPRESA e ON e.ID = pd.EMPRESA_ID WHERE pd.CICLO_ID = {{cicloId}}),JSON_ARRAY()) AS DISSIDIOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',pt.ID,'CICLO_ID',pt.CICLO_ID,'EMPRESA_ID',pt.EMPRESA_ID,'PERCENTUAL',pt.PERCENTUAL,'CRIADO_EM',pt.CRIADO_EM,'EMPRESA_NOME',e.NOME)) FROM PREMISSA_TURNOVER pt JOIN EMPRESA e ON e.ID = pt.EMPRESA_ID WHERE pt.CICLO_ID = {{cicloId}}),JSON_ARRAY()) AS TURNOVERS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',a.ID,'CICLO_ID',a.CICLO_ID,'COLABORADOR_ID',a.COLABORADOR_ID,'PERCENTUAL',a.PERCENTUAL,'MES_APLICACAO',a.MES_APLICACAO,'MOTIVO',a.MOTIVO,'CRIADO_EM',a.CRIADO_EM,'COLAB_NOME',c.NOME,'SALARIO',c.SALARIO)) FROM AUMENTO_SALARIAL a JOIN COLABORADOR c ON c.ID = a.COLABORADOR_ID WHERE a.CICLO_ID = {{cicloId}}),JSON_ARRAY()) AS AUMENTOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',d.ID,'CICLO_ID',d.CICLO_ID,'CR_ID',d.CR_ID,'COLABORADOR_ID',d.COLABORADOR_ID,'MES_DESLIGAMENTO',d.MES_DESLIGAMENTO,'CRIADO_EM',d.CRIADO_EM,'COLAB_NOME',c.NOME)) FROM DESLIGAMENTO_PROJETADO d JOIN COLABORADOR c ON c.ID = d.COLABORADOR_ID WHERE d.CICLO_ID = {{cicloId}} AND d.CR_ID IN (SELECT DISTINCT crc2.CR_ID FROM CR_CONTA crc2
 LEFT JOIN CONTA_DRIVER_EXCECAO cde2 ON cde2.CR_ID = crc2.CR_ID AND cde2.CONTA_ID = crc2.CONTA_ID AND cde2.ATIVO = true
 LEFT JOIN CONTA_DRIVER cd2 ON cd2.CONTA_ID = crc2.CONTA_ID
 WHERE crc2.ATIVO = true AND COALESCE(cde2.PACOTE_ID, cd2.PACOTE_ID, cde2.DRIVER_ID, cd2.DRIVER_ID) = {{pkgId}})),JSON_ARRAY()) AS DESLIGAMENTOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'CICLO_ID',t.CICLO_ID,'CR_ID',t.CR_ID,'CONTA_ID',t.CONTA_ID,'PERCENTUAL',t.PERCENTUAL,'MODO',t.MODO,'JUSTIFICATIVA',t.JUSTIFICATIVA,'CRIADO_EM',t.CRIADO_EM)) FROM HIST_PREMISSA t WHERE t.CICLO_ID = {{cicloId}} AND t.CR_ID IN (SELECT DISTINCT crc2.CR_ID FROM CR_CONTA crc2
 LEFT JOIN CONTA_DRIVER_EXCECAO cde2 ON cde2.CR_ID = crc2.CR_ID AND cde2.CONTA_ID = crc2.CONTA_ID AND cde2.ATIVO = true
 LEFT JOIN CONTA_DRIVER cd2 ON cd2.CONTA_ID = crc2.CONTA_ID
 WHERE crc2.ATIVO = true AND COALESCE(cde2.PACOTE_ID, cd2.PACOTE_ID, cde2.DRIVER_ID, cd2.DRIVER_ID) = {{pkgId}})),JSON_ARRAY()) AS HIST_PREMISSA,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'FORMULA_ID',t.FORMULA_ID,'CICLO_ID',t.CICLO_ID,'CR_ID',t.CR_ID,'MES',t.MES,'VALOR',t.VALOR,'PACOTE_ID',t.PACOTE_ID)) FROM DRIVER_FORMULA_VALOR t WHERE t.CICLO_ID = {{cicloId}} AND t.CR_ID IN (SELECT DISTINCT crc2.CR_ID FROM CR_CONTA crc2
 LEFT JOIN CONTA_DRIVER_EXCECAO cde2 ON cde2.CR_ID = crc2.CR_ID AND cde2.CONTA_ID = crc2.CONTA_ID AND cde2.ATIVO = true
 LEFT JOIN CONTA_DRIVER cd2 ON cd2.CONTA_ID = crc2.CONTA_ID
 WHERE crc2.ATIVO = true AND COALESCE(cde2.PACOTE_ID, cd2.PACOTE_ID, cde2.DRIVER_ID, cd2.DRIVER_ID) = {{pkgId}})),JSON_ARRAY()) AS CLV,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'FORMULA_ID',t.FORMULA_ID,'CR_ID',t.CR_ID,'TIPO',t.TIPO,'FORMULA',t.FORMULA,'CRIADO_EM',t.CRIADO_EM)) FROM DRIVER_FORMULA_CR t WHERE t.CR_ID IN (SELECT DISTINCT crc2.CR_ID FROM CR_CONTA crc2
 LEFT JOIN CONTA_DRIVER_EXCECAO cde2 ON cde2.CR_ID = crc2.CR_ID AND cde2.CONTA_ID = crc2.CONTA_ID AND cde2.ATIVO = true
 LEFT JOIN CONTA_DRIVER cd2 ON cd2.CONTA_ID = crc2.CONTA_ID
 WHERE crc2.ATIVO = true AND COALESCE(cde2.PACOTE_ID, cd2.PACOTE_ID, cde2.DRIVER_ID, cd2.DRIVER_ID) = {{pkgId}})),JSON_ARRAY()) AS OVERRIDES,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'CICLO_ID',t.CICLO_ID,'CONTA_ID',t.CONTA_ID,'PERCENTUAL',t.PERCENTUAL,'CRIADO_EM',t.CRIADO_EM)) FROM PREMISSA_IMPOSTO t WHERE t.CICLO_ID = {{cicloId}}),JSON_ARRAY()) AS IMPOSTO_CENTRAL,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'CICLO_ID',t.CICLO_ID,'DRIVER_ID',t.DRIVER_ID,'GESTOR_ID',t.GESTOR_ID,'STATUS',t.STATUS,'COMENTARIO',t.COMENTARIO,'ATUALIZADO_EM',t.ATUALIZADO_EM,'DRIVERS_CONFIRMADOS',t.DRIVERS_CONFIRMADOS,'TOTAL_MODELOS',t.TOTAL_MODELOS)) FROM PACOTE_STATUS t WHERE t.CICLO_ID = {{cicloId}} AND t.DRIVER_ID = {{pkgId}}),JSON_ARRAY()) AS STATUS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'PACOTE_ID',t.PACOTE_ID,'CONTA_ID',t.CONTA_ID,'MODELO',t.MODELO,'MODE',t.MODE,'ATUALIZADO_EM',t.ATUALIZADO_EM)) FROM PKG_RATEIO_CONFIG t WHERE t.PACOTE_ID = {{pkgId}}),JSON_ARRAY()) AS PKG_RATEIO_CONFIG,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'NOME',t.NOME,'DESCRICAO',t.DESCRICAO,'ATIVO',t.ATIVO,'CRIADO_EM',t.CRIADO_EM,'TIPO',t.TIPO)) FROM RATEIO t WHERE t.ATIVO = true),JSON_ARRAY()) AS RATEIOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'RATEIO_ID',t.RATEIO_ID,'CR_ID',t.CR_ID,'QUANTIDADE',t.QUANTIDADE)) FROM RATEIO_ITEM t WHERE 1=1),JSON_ARRAY()) AS RATEIO_ITENS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',pl.ID,'NOME',pl.NOME,'ORDEM',pl.ORDEM,'MES',pv.MES,'VALOR',pv.VALOR)) FROM PREMISSA_LINHA pl LEFT JOIN PREMISSA_VALOR pv ON pv.LINHA_ID = pl.ID WHERE pl.CICLO_ID = {{cicloId}}),JSON_ARRAY()) AS PREMISSAS
FROM PREENCHIMENTO_TOKEN tk
WHERE tk.TOKEN = '{{token}}' AND tk.ATIVO = 'true'
  AND tk.CICLO_ID = {{cicloId}}
  AND EXISTS (SELECT 1 FROM PACOTE_STATUS ps WHERE ps.CICLO_ID = tk.CICLO_ID AND ps.GESTOR_ID = tk.GESTOR_ID AND ps.DRIVER_ID = {{pkgId}})
LIMIT 1